/**
 * Key map node (generated by `npm run codegen`):
 * - `p`: camelCase property → `[snake_case name, child node?]`
 * - `a`: node for the values of free-form maps (their keys are never renamed)
 * - `i`: node for array items, `r`: a single value must be wrapped into an array
 * - `n`: shared type normalized by hand (filters, trigger, ranges, Molang)
 */
export interface KeyMapNode {
  n?: SharedKind;
  p?: Record<string, [string, KeyMapNode?, FieldMarker?]>;
  a?: KeyMapNode;
  i?: KeyMapNode;
  r?: 1;
  /** `number | range`: plain numbers stay numbers. */
  s?: 1;
}

/** Field lifecycle marker: deprecated (warning), removed (error + not written from `since`), introduced in `since`. */
export type FieldMarker =
  | { d: string }
  | { r: { since: string; replacement?: string[] } }
  | { s: string };

export type SharedKind =
  | 'filters'
  | 'trigger'
  | 'range-object'
  | 'range-any'
  | 'range-int-or-object'
  | 'molang'
  | 'molang-number';

export interface GeneratedEntry {
  /** Minecraft key, e.g. `minecraft:behavior.avoid_block`. */
  key: string;
  /** SDK key, e.g. `avoidBlock`. */
  sdkKey: string;
  kind: string;
  /** Component without properties: `{ value?: boolean }` sugar; `'boolean'` also accepts a bare boolean. */
  flag: boolean | 'boolean';
  /** Not in the Bedrock schemas (removed/unknown upstream): a warning is reported. */
  deprecated: boolean | string;
  /** Removed from the schemas (official Mojang schemas): error when the format version is `since` or newer. */
  removed?: { since: string; reason?: string; replacement?: string[] };
  /** Free-form component: keys are written as is (reason from the patch). */
  freeForm?: string;
  map: KeyMapNode;
  validate: ((data: unknown) => boolean) & {
    errors?: { instancePath: string; schemaPath?: string; keyword: string; message?: string; params: Record<string, unknown> }[] | null;
  };
}
